input.content:
/* 담은 항목 목록 스타일 (SPEC.md I13). index.css의 색 토큰을 재사용한다. */

.cart {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  padding: 32px 20px 48px;
  box-sizing: border-box;
  text-align: left;
}

.cart h2 {
  margin-bottom: 20px;
}

.cart-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--border);
}

.cart-line {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  align-items: center;
  gap: 8px 20px;
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
}

.cart-name {
  color: var(--text-h);
  font-size: 17px;
}

.cart-unit-price,
.cart-subtotal {
  font-family: var(--mono);
  font-size: 15px;
  white-space: nowrap;
}

.cart-subtotal {
  color: var(--text-h);
  min-width: 96px;
  text-align: right;
}

.cart-label {
  display: block;
  font-family: var(--sans);
  font-size: 12px;
  letter-spacing: 0.4px;
  color: var(--text);
  opacity: 0.7;
}

.cart-stepper {
