/**
 * 담은 항목 목록. 요구와 근거는 SPEC.md 참조.
 * - 줄마다 이름 · 단가 · 수량 · 소계 (S2, S3)
 * - 아이콘만 있는 −/+ 스테퍼로 수량 ±1 (S4, S5, S6)
 * - 수량 0 = 더 이상 담긴 것이 아님 → 줄 제거 + 합계 제외 (S8, I1)
 */
import { useState } from 'react';
import { formatWon } from './formatWon';
import './CartList.css';

export type CartItem = {
  id: string;
  name: string;
  /** 단가. 정수 원 단위 (SPEC.md I8) */
  unitPrice: number;
  quantity: number;
};

type CartListProps = {
  /** 생략하면 하드코딩된 시작 데이터를 쓴다 (SPEC.md S10, I11) */
  items?: CartItem[];
};

/** 시작 데이터 (SPEC.md S10) */
const INITIAL_ITEMS: CartItem[] = [
  { id: 'apple', name: '유기농 사과 1kg', unitPrice: 12000, quantity: 2 },
  { id: 'beans', name: '핸드드립 원두 200g', unitPrice: 18500, quantity: 1 },
  { id: 'towel', name: '면 워시타월 3매', unitPrice: 6900, quantity: 3 },
];

/**
 * 정수 원화를 천 단위 쉼표 + '원'으로 적는다 (SPEC.md I8).
 * Intl·로케일에 기대지 않아 어느 실행 환경에서도 같은 문자열을 낸다.
 */
export function formatWon(amount: number): string {
  return `${amount.toString().replace(/\B(?=(\d{3})+$)/g, ',')}원`;
}

export default function CartList({ items = INITIAL_ITEMS }: CartListProps) {
  const [lines, setLines] = useState<CartItem[]>(items);

  function changeQuantity(id: string, delta: number) {
    setLines((prev) =>
      prev.flatMap((line) => {
        if (line.id !== id) return [line]; // 다른 줄은 그대로 (S7)
        const nextQuantity = line.quantity + delta;
        return nextQuantity <= 0 ? [] : [{ ...line, quantity: nextQuantity }]; // (S8)
      }),
    );
  }

  const total = lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0);

  return (
    <section className="cart" aria-labelledby="cart-heading">
      <h2 id="cart-heading">장바구니</h2>

      {lines.length === 0 ? (
        <p className="cart-empty">담은 항목이 없습니다.</p>
      ) : (
        <ul className="cart-lines">
          {lines.map((line) => (
            <li key={line.id} className="cart-line">
              <span className="cart-name">{line.name}</span>
              <span className="cart-unit-price">
                <span className="cart-label">단가</span>
                {formatWon(line.unitPrice)}
              </span>
              <span className="cart-stepper" role="group" aria-label={`${line.name} 수량 조절`}>
                <button
                  type="button"
                  className="cart-step"
                  aria-label={`${line.name} 수량 줄이기`}
                  onClick={() => changeQuantity(line.id, -1)}
                >
                  <span aria-hidden="true">−</span>
                </button>
                <span className="cart-quantity" aria-live="polite">
                  {line.quantity}
                </span>
                <button
                  type="button"
                  className="cart-step"
                  aria-label={`${line.name} 수량 늘리기`}
                  onClick={() => changeQuantity(line.id, 1)}
                >
                  <span aria-hidden="true">+</span>
                </button>
              </span>
              <span className="cart-subtotal">
                <span className="cart-label">소계</span>
                {formatWon(line.unitPrice * line.quantity)}
              </span>
            </li>
          ))}
        </ul>
      )}

      <p className="cart-total">
        <span>합계</span>
        <strong>{formatWon(total)}</strong>
      </p>
    </section>
  );
}

/**
 * 지키는 요구 (SPEC.md §1):
 * - S2 "담긴 항목이 하나 이상이면 CartList는 각 항목을 한 줄로 렌더하고, 그 줄은 항목 이름 ·
 *   단가 · 수량 · 소계 네 값을 모두 표시한다."
 * - S3 "각 줄의 소계는 그 줄의 `수량 × 단가`와 같다."
 * - S9 "목록 아래에 전체 합계가 표시되고, 그 값은 담긴 모든 줄의 소계 합과 같다."
 * - S10 "시작 데이터는 CartList 모듈 안에 하드코딩된 항목 2~3개다."
 * - I8 "금액은 정수 원화이고, 천 단위 쉼표 + `원` 접미사로 표시한다. 표시 포맷은 실행 환경의
 *   로케일·ICU 설정에 의존하지 않는다."
 */
import { afterEach, describe, expect, test } from 'vitest';
import { cleanup, render, screen, within } from '@testing-library/react';
import CartList, { formatWon, type CartItem } from './CartList';

afterEach(cleanup);

const FIXTURE: CartItem[] = [
  { id: 'a', name: '사과', unitPrice: 1000, quantity: 2 },
  { id: 'b', name: '원두', unitPrice: 2500, quantity: 1 },
];

describe('줄 구성과 합계', () => {
  test('담긴 항목마다 한 줄이 있고 이름·단가·수량·소계를 모두 보여준다 (S2, S3)', () => {
    render(<CartList items={FIXTURE} />);

    const lines = screen.getAllByRole('listitem');
    expect(lines).toHaveLength(2);

    expect(lines[0].textContent).toContain('사과');
    expect(lines[0].textContent).toContain('1,000원'); // 단가
    expect(within(lines[0]).getByText('2')).toBeTruthy(); // 수량
    expect(lines[0].textContent).toContain('2,000원'); // 소계 = 2 × 1,000

    expect(lines[1].textContent).toContain('원두');
    expect(lines[1].textContent).toContain('2,500원'); // 단가이자 소계 = 1 × 2,500
    expect(within(lines[1]).getByText('1')).toBeTruthy();
  });

  test('전체 합계는 모든 줄 소계의 합이고 목록 뒤에 온다 (S9)', () => {
    const { container } = render(<CartList items={FIXTURE} />);

    // 2 × 1,000 + 1 × 2,500
    expect(screen.getByText('4,500원').textContent).toBe('4,500원');

    const list = container.querySelector('ul');
    const total = container.querySelector('.cart-total');
    expect(list).not.toBeNull();
    expect(total).not.toBeNull();
    // 합계가 목록보다 뒤에 있다 = 문서 순서상 list가 total보다 앞
    expect(
      list!.compareDocumentPosition(total!) & Node.DOCUMENT_POSITION_FOLLOWING,
    ).toBeTruthy();
  });

  test('props 없이 렌더하면 하드코딩된 시작 항목 2~3개가 나온다 (S10)', () => {
    render(<CartList />);

    const lines = screen.getAllByRole('listitem');
    expect(lines.length).toBeGreaterThanOrEqual(2);
    expect(lines.length).toBeLessThanOrEqual(3);
    for (const line of lines) {
      expect(within(line).getAllByRole('button')).toHaveLength(2);
    }
  });

  test('금액 표기는 천 단위 쉼표 + 원이고 로케일에 의존하지 않는다 (I8)', () => {
    expect(formatWon(0)).toBe('0원');
    expect(formatWon(999)).toBe('999원');
    expect(formatWon(1000)).toBe('1,000원');
    expect(formatWon(1234567)).toBe('1,234,567원');
  });
});

